head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#wq_uuid_5_item_0_autocomplete_column3_label').text().trim() == '빈 값' || WebSquare.wUnit.getJq('#wq_uuid_5_item_0_autocomplete_column3_label').text().trim() == 'Empty';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 4. 브라우저에서 name1 의 ▼ 버튼을 클릭후 사용자필터를 클릭한다.
    //4. In the browser, click the ▼ button for name1 and then click the user filter.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_column9_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. name1 의 사용자필터가 생성된다. (필터표시는 label 인 '1' 로 표시된다.) 
    //4. The user filter for name1 is created. (The filter indicator is labeled '1'.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_customFilter').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_item_0_autocomplete_column9_label').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_item_1_autocomplete_label').text() == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. 임의로 선택해서 사용자필터를 적용한다.
    //5. Select and apply a custom filter.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_selectbox_column9_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_selectbox_column9_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_btnConform_column9').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 설정한 사용자 필터가 적용된다.
    //5. The set user filter is applied.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_0_0').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_1_0').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_2_0').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_3_0').text() == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. 브라우저에서 name2 의 ▼ 버튼을 클릭후 사용자필터를 클릭한다.
    //6. In the browser, click the button for name2, and then click the user filter.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_column7_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. name2 의 사용자필터가 생성된다. (필터표시는 value 인 '11' 로 표시된다.) 
    //6. The user filter for name2 is created. (The filter display is indicated by the value '11'.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_customFilter').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_item_0_autocomplete_column7_label').text() == '22'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_item_1_autocomplete_label').text() == '22'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 7. 임의로 선택해서 사용자필터를 적용한다.
    //7. Apply the user filter by selecting it at random.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_selectbox_column7_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_selectbox_column7_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_btnConform_column7').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 7. 설정한 사용자 필터('22)가 적용된다.
    //7. The set user filter ('22') is applied.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_0_1').text() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_1_1').text() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_2_1').text() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_3_1').text() == '2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 8. 브라우저에서 name3 의 ▼ 버튼을 클릭후 사용자필터를 클릭한다.
    //8. In your browser, click the button for name3, and then click Custom Filter.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_column3_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 8. name3 의 사용자필터가 생성된다. (필터표시는 label 인 '1' 로 표시된다.)
    //8. The user filter for name3 is created. (The filter indicator is labeled '1'.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_customFilter').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 9. 임의로 선택해서 사용자필터('3')를 적용한다.
    //9. Choose arbitrarily and apply the user filter ('3').
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_selectbox_column3_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_selectbox_column3_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_autocomplete_column3_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_item_0_autocomplete_column3_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_btnConform_column3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 9. 설정한 사용자 필터('3')가 적용된다
    //9. The set user filter ('3') is applied.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_0_2').text() == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_1_2').text() == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_2_2').text() == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_cell_3_2').text() == '3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList2.setData([11, 22, 33, 33, 22, 11, 22, 33, 11, 11, 22, 33, 33, 22, 11, 22, 33, 11, 11, 22, 33, 33, 22, 11, 22, 33, 11, 11, 22, 33, 33, 22, 11, 22, 33, 55]);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 02-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
